import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";
import type { AgentAnnouncerController } from "./hooks/use-agent-announcer";

export type AgentAnnouncerProps = Omit<
  ComponentProps<"span">,
  "children" | "role"
> & {
  announcer: AgentAnnouncerController;
};

/** The conversation's one status region. Render it once, outside the scrolling log. */
export function AgentAnnouncer({
  announcer,
  className,
  ...props
}: AgentAnnouncerProps): ReactElement {
  return (
    <span
      aria-atomic="true"
      aria-live="polite"
      data-slot="agent-announcer"
      role="status"
      className={cn("sr-only", className)}
      {...props}
    >
      {announcer.message}
    </span>
  );
}

"use client";

import type { ReactElement, UIEvent } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  ChatConversation,
  type ChatConversationProps,
} from "../chat/chat-conversation";
import {
  AGENT_SCROLL_OFFSET_VAR,
  getAgentScrollOffset,
} from "./lib/get-agent-scroll-offset";

export type AgentConversationProps = ChatConversationProps;

export function AgentConversation({
  scroll,
  live = "off",
  contentClassName,
  ...props
}: AgentConversationProps): ReactElement {
  const onScroll = (event: UIEvent<HTMLDivElement>): void => {
    event.currentTarget.style.setProperty(
      AGENT_SCROLL_OFFSET_VAR,
      getAgentScrollOffset(event.currentTarget.scrollTop),
    );
    scroll.onScroll(event);
  };

  return (
    <ChatConversation
      data-slot="agent-conversation"
      scroll={{ ...scroll, onScroll }}
      live={live}
      contentClassName={cn(
        // Inside a popover crossfade snapshot ([data-previous]), keep the reader's place.
        // The variable is AGENT_SCROLL_OFFSET_VAR; Tailwind needs it spelled out here.
        "flex in-data-previous:-translate-y-(--agent-conversation-scroll-top) flex-col gap-6 pt-4",
        contentClassName,
      )}
      {...props}
    />
  );
}

"use client";

import { ChevronRightIcon } from "lucide-react";
import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";
import { CollapsibleTrigger } from "@/registry/default/ui/collapsible";

export type AgentDisclosureTriggerProps = ComponentProps<
  typeof CollapsibleTrigger
>;

/** The trigger reasoning and tool activity share: its content, then a chevron that turns when open. */
export function AgentDisclosureTrigger({
  className,
  children,
  ...props
}: AgentDisclosureTriggerProps): ReactElement {
  return (
    <CollapsibleTrigger
      className={cn(
        "flex w-fit min-w-0 max-w-full cursor-pointer items-start gap-1.5 rounded-sm text-start text-muted-foreground text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background",
        className,
      )}
      data-slot="agent-disclosure-trigger"
      {...props}
    >
      {children}
      <ChevronRightIcon
        aria-hidden="true"
        className="h-lh w-3.5 shrink-0 in-data-panel-open:rotate-90 transition-transform motion-reduce:transition-none rtl:in-data-panel-open:-rotate-90 rtl:-scale-x-100"
      />
    </CollapsibleTrigger>
  );
}

"use client";

import type { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import { CheckIcon, CopyIcon, PencilIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useCopyToClipboard } from "@/registry/default/hooks/use-copy-to-clipboard";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import { Toolbar, ToolbarButton } from "@/registry/default/ui/toolbar";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";

export type AgentMessageActionsProps = Omit<
  ToolbarPrimitive.Root.Props,
  "aria-label"
> & {
  label: string;
};

export function AgentMessageActions({
  label,
  className,
  ...props
}: AgentMessageActionsProps): ReactElement {
  return (
    <Toolbar
      aria-label={label}
      data-slot="agent-message-actions"
      className={cn(
        "w-fit gap-0.5 rounded-none border-0 bg-transparent p-0 transition-opacity motion-reduce:transition-none",
        // Inside a message on a fine pointer, hide until the message is hovered or focused,
        // or a popup from an action is open. Coarse pointers always show the actions.
        "pointer-fine:in-[[data-slot=agent-message]:not(:hover):not(:focus-within):not([data-actions-visible]):not(:has([data-popup-open]))]:opacity-0",
        className,
      )}
      {...props}
    />
  );
}

export type AgentMessageActionProps = Omit<
  ButtonProps,
  "aria-label" | "children" | "size" | "variant"
> & {
  label: string;
  children: ReactNode;
  /** Tooltip content. Defaults to `label`. */
  tooltip?: ReactNode;
};

export function AgentMessageAction({
  label,
  children,
  tooltip = label,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentMessageActionProps): ReactElement {
  // An action that can't do anything is a real disabled button, never aria-disabled alone.
  const inactive = disabled || (!onClick && !render);
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <ToolbarButton
            disabled={inactive}
            focusableWhenDisabled={false}
            render={
              <Button
                aria-label={label}
                className={cn(
                  "text-muted-foreground hover:text-foreground",
                  className,
                )}
                data-slot="agent-message-action"
                disabled={inactive}
                onClick={onClick}
                render={render}
                size="icon-xs"
                variant="ghost"
                {...props}
              />
            }
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipPopup>{tooltip}</TooltipPopup>
    </Tooltip>
  );
}

export type AgentMessageCopyActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render" | "tooltip"
> & {
  text: string;
  copiedLabel: string;
  /** Called after the text reaches the clipboard. Announce `copiedLabel` here; the button's name stays `label`. */
  onCopy?: () => void;
};

export function AgentMessageCopyAction({
  text,
  label,
  copiedLabel,
  onCopy,
  disabled,
  ...props
}: AgentMessageCopyActionProps): ReactElement {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ onCopy });
  return (
    <AgentMessageAction
      data-copied={isCopied || undefined}
      disabled={disabled || !text}
      label={label}
      tooltip={isCopied ? copiedLabel : label}
      onClick={() => copyToClipboard(text)}
      {...props}
    >
      {isCopied ? (
        <CheckIcon aria-hidden="true" />
      ) : (
        <CopyIcon aria-hidden="true" />
      )}
    </AgentMessageAction>
  );
}

export type AgentMessageEditActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render"
> & {
  onEdit: () => void;
};

export function AgentMessageEditAction({
  onEdit,
  ...props
}: AgentMessageEditActionProps): ReactElement {
  return (
    <AgentMessageAction onClick={onEdit} {...props}>
      <PencilIcon aria-hidden="true" />
    </AgentMessageAction>
  );
}

import type { ReactElement, ReactNode } from "react";
import { ChatBubble } from "../chat/chat-bubble";
import {
  ChatMessageAvatar,
  ChatMessageContent,
  ChatMessageFooter,
  ChatMessageLayout,
  type ChatMessageLayoutProps,
} from "../chat/chat-message-layout";
import { ChatMessageText } from "../chat/chat-message-text";

export type AgentMessageProps = Omit<ChatMessageLayoutProps, "align"> & {
  from: "user" | "assistant";
  /** The agent's identity mark beside an assistant reply. Ignored on user messages. */
  avatar?: ReactNode;
  actions?: ReactNode;
  /** Keep actions shown instead of revealing them on hover and focus. */
  actionsAlwaysVisible?: boolean;
  footer?: ReactNode;
  streaming?: boolean;
};

export function AgentMessage({
  from,
  avatar,
  actions,
  actionsAlwaysVisible = false,
  footer,
  streaming,
  children,
  ...props
}: AgentMessageProps): ReactElement {
  const user = from === "user";
  const content =
    typeof children === "string" ? (
      <ChatMessageText text={children} />
    ) : (
      children
    );

  return (
    <ChatMessageLayout
      align={user ? "end" : "start"}
      data-slot="agent-message"
      data-from={from}
      data-actions-visible={actionsAlwaysVisible || undefined}
      {...props}
    >
      {!user && avatar && <ChatMessageAvatar>{avatar}</ChatMessageAvatar>}
      <ChatMessageContent streaming={streaming}>
        {user ? (
          <ChatBubble align="end" className="max-w-[83%]">
            {content}
          </ChatBubble>
        ) : (
          content
        )}
        {actions}
        {footer && <ChatMessageFooter>{footer}</ChatMessageFooter>}
      </ChatMessageContent>
    </ChatMessageLayout>
  );
}

"use client";

import {
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useEffect,
  useReducer,
} from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  Collapsible,
  CollapsiblePanel,
} from "@/registry/default/ui/collapsible";
import { AgentDisclosureTrigger } from "./agent-disclosure-trigger";
import { AgentStatusIndicator } from "./agent-status-indicator";
import {
  AGENT_REASONING_CLOSE_DELAY,
  getAgentReasoningState,
  getInitialAgentReasoningState,
} from "./lib/get-agent-reasoning-state";

export type AgentReasoningProps = Omit<
  ComponentProps<typeof Collapsible>,
  "children" | "defaultOpen" | "onOpenChange" | "open"
> & {
  children: ReactNode;
  /** Shown while the reasoning streams, such as “Thinking…”. */
  streamingLabel: string;
  /** Shown once it finishes, such as “Thought for 4 seconds”. */
  completedLabel: string;
  streaming?: boolean;
  /** Open on mount. `false` also stops it opening when streaming starts. Defaults to `streaming`. */
  defaultOpen?: boolean;
  /** Replaces the neutral busy glyph while streaming. */
  indicator?: ReactNode;
};

/**
 * Reasoning behind a disclosure. It opens while streaming and closes a second after
 * it finishes, unless the user has opened or closed it in the meantime.
 */
export function AgentReasoning({
  children,
  streamingLabel,
  completedLabel,
  streaming = false,
  defaultOpen,
  indicator,
  className,
  ...props
}: AgentReasoningProps): ReactElement {
  const [state, dispatch] = useReducer(getAgentReasoningState, undefined, () =>
    getInitialAgentReasoningState(streaming, defaultOpen),
  );

  useEffect(() => {
    dispatch({ autoOpen: defaultOpen !== false, streaming, type: "stream" });
  }, [defaultOpen, streaming]);

  useEffect(() => {
    if (!state.closing) return;
    const timeout = window.setTimeout(
      () => dispatch({ type: "close" }),
      AGENT_REASONING_CLOSE_DELAY,
    );
    return () => window.clearTimeout(timeout);
  }, [state.closing]);

  return (
    <Collapsible
      className={cn("flex min-w-0 flex-col", className)}
      data-slot="agent-reasoning"
      data-streaming={streaming || undefined}
      open={state.open}
      onOpenChange={(open) => dispatch({ open, type: "toggle" })}
      {...props}
    >
      <AgentDisclosureTrigger data-slot="agent-reasoning-trigger">
        <AgentStatusIndicator
          indicator={indicator}
          status={streaming ? "thinking" : "done"}
        >
          {streaming ? streamingLabel : completedLabel}
        </AgentStatusIndicator>
      </AgentDisclosureTrigger>
      <CollapsiblePanel className="motion-reduce:transition-none">
        <div
          aria-busy={streaming || undefined}
          className="whitespace-pre-wrap ps-5 pt-2 text-muted-foreground text-xs/relaxed"
          data-slot="agent-reasoning-content"
        >
          {children}
        </div>
      </CollapsiblePanel>
    </Collapsible>
  );
}

"use client";

import type { useRender } from "@base-ui/react/use-render";
import { ChevronsDownUpIcon, ChevronsUpDownIcon } from "lucide-react";
import { type ReactElement, type ReactNode, useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Card } from "@/registry/default/ui/card";
import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "@/registry/default/ui/collapsible";
import {
  AGENT_RESULT_LIST_PREVIEW_COUNT,
  splitAgentResultItems,
} from "./lib/split-agent-result-items";

export type AgentResultItem = {
  id: string;
  title: string;
  /** Short secondary text after the title, such as a time. */
  description?: string;
  /** Shown at the end of the row, such as badges. */
  trailing?: ReactNode;
  /** Makes the row a link. */
  href?: string;
  /** The link's accessible name. Defaults to the title. */
  label?: string;
};

export type AgentResultListProps = Omit<
  useRender.ComponentProps<"div">,
  "children"
> & {
  items: readonly AgentResultItem[];
  /** Rows shown before “show more”. A leftover of one row is shown instead of hidden. */
  previewCount?: number;
  /** The toggle's label while rows are hidden, given how many. */
  showMoreLabel: (hiddenCount: number) => string;
  showLessLabel: string;
};

const rowClassName = "flex items-center gap-2 px-3 py-2 text-xs";
const interactiveRowClassName =
  "outline-none hover:bg-accent focus-visible:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset";

function AgentResultRows({
  items,
}: {
  items: readonly AgentResultItem[];
}): ReactElement {
  return (
    <ul className="flex flex-col">
      {items.map((item) => {
        const content = (
          <>
            <span className="flex min-w-0 flex-1 items-center gap-2">
              <span className="min-w-0 truncate font-medium text-foreground">
                {item.title}
              </span>
              {item.description && (
                <span className="shrink-0 text-muted-foreground">
                  {item.description}
                </span>
              )}
            </span>
            {item.trailing && (
              <span className="flex shrink-0 items-center gap-1.5">
                {item.trailing}
              </span>
            )}
          </>
        );
        return (
          <li
            className="not-first:border-t"
            data-slot="agent-result-list-item"
            key={item.id}
          >
            {item.href ? (
              <a
                aria-label={item.label ?? item.title}
                className={cn(rowClassName, interactiveRowClassName)}
                href={item.href}
              >
                {content}
              </a>
            ) : (
              <div className={rowClassName}>{content}</div>
            )}
          </li>
        );
      })}
    </ul>
  );
}

function AgentResultListRemainder({
  hidden,
  showMoreLabel,
  showLessLabel,
}: {
  hidden: readonly AgentResultItem[];
  showMoreLabel: (hiddenCount: number) => string;
  showLessLabel: string;
}): ReactElement {
  const [open, setOpen] = useState(false);
  const Icon = open ? ChevronsDownUpIcon : ChevronsUpDownIcon;
  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <CollapsiblePanel className="border-t motion-reduce:transition-none">
        <AgentResultRows items={hidden} />
      </CollapsiblePanel>
      <CollapsibleTrigger
        className={cn(
          rowClassName,
          interactiveRowClassName,
          "w-full cursor-pointer border-t text-start text-muted-foreground",
        )}
        data-slot="agent-result-list-toggle"
      >
        <Icon aria-hidden="true" className="size-3.5 shrink-0" />
        {open ? showLessLabel : showMoreLabel(hidden.length)}
      </CollapsibleTrigger>
    </Collapsible>
  );
}

/** A card of result rows. Long lists show the first rows and put the rest behind a toggle. */
export function AgentResultList({
  items,
  previewCount = AGENT_RESULT_LIST_PREVIEW_COUNT,
  showMoreLabel,
  showLessLabel,
  className,
  ...props
}: AgentResultListProps): ReactElement | null {
  if (items.length === 0) return null;
  const { visible, hidden } = splitAgentResultItems(items, previewCount);
  return (
    <Card
      className={cn("w-full min-w-0 overflow-hidden", className)}
      data-slot="agent-result-list"
      {...props}
    >
      <AgentResultRows items={visible} />
      {hidden.length > 0 && (
        <AgentResultListRemainder
          // A new result set starts collapsed again.
          key={items.map((item) => item.id).join("\0")}
          hidden={hidden}
          showLessLabel={showLessLabel}
          showMoreLabel={showMoreLabel}
        />
      )}
    </Card>
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import {
  CircleCheckIcon,
  CircleStopIcon,
  CircleXIcon,
  LoaderCircleIcon,
} from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import type { AgentPhase } from "./lib/get-agent-announcement";

export type AgentStatus = Extract<
  AgentPhase,
  "thinking" | "working" | "done" | "stopped" | "failed"
>;

export type AgentStatusIndicatorProps = useRender.ComponentProps<"span"> & {
  status: AgentStatus;
  /** Replaces the neutral busy glyph while thinking or working, such as a brand loader. */
  indicator?: ReactNode;
};

const settledIcons = {
  done: CircleCheckIcon,
  failed: CircleXIcon,
  stopped: CircleStopIcon,
};

function isAgentStatusBusy(
  status: AgentStatus,
): status is "thinking" | "working" {
  return status === "thinking" || status === "working";
}

/**
 * A status line: a glyph and its label. It never announces itself; route phase
 * changes through the conversation's announcer. While busy, the label shimmers
 * with `--agent-shimmer`, a gradient image you can set on any ancestor.
 */
export function AgentStatusIndicator({
  status,
  indicator,
  className,
  children,
  render,
  ...props
}: AgentStatusIndicatorProps): ReactElement {
  const Icon = isAgentStatusBusy(status) ? undefined : settledIcons[status];
  const busy = !Icon;
  const defaultProps = {
    children: (
      <>
        <span
          aria-hidden="true"
          className="flex h-lh w-3.5 shrink-0 items-center justify-center [&_svg:not([class*='size-'])]:size-3.5"
          data-slot="agent-status-indicator-glyph"
        >
          {Icon ? (
            <Icon />
          ) : (
            (indicator ?? (
              <LoaderCircleIcon className="motion-safe:animate-spin" />
            ))
          )}
        </span>
        <span
          className={cn(
            "min-w-0 [overflow-wrap:anywhere]",
            busy &&
              // Purple to rose by default. The base layer keeps the text readable between sweeps.
              "motion-safe:animate-[skeleton_1.2s_-0.6s_infinite_linear] motion-safe:bg-clip-text motion-safe:text-transparent motion-safe:[background-image:var(--agent-shimmer,linear-gradient(105deg,transparent_12%,--alpha(var(--color-info-foreground)/72%)_32%,--alpha(var(--color-purple-500)/76%)_50%,--alpha(var(--color-rose-500)/68%)_68%,transparent_88%)),linear-gradient(var(--color-muted-foreground),var(--color-muted-foreground))] motion-safe:[background-size:200%_100%,100%_100%]",
          )}
          data-slot="agent-status-indicator-label"
        >
          {children}
        </span>
      </>
    ),
    className: cn(
      "inline-flex min-w-0 max-w-full items-start gap-1.5 text-muted-foreground text-xs",
      status === "failed" && "font-medium text-destructive-foreground",
      className,
    ),
    "data-slot": "agent-status-indicator",
    "data-status": status,
  };

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(defaultProps, props),
    render,
  });
}

"use client";

import { WrenchIcon } from "lucide-react";
import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  Collapsible,
  CollapsiblePanel,
} from "@/registry/default/ui/collapsible";
import { AgentDisclosureTrigger } from "./agent-disclosure-trigger";
import { AgentStatusIndicator } from "./agent-status-indicator";
import {
  type AgentToolActivityLabels,
  type AgentToolCall,
  getAgentToolSummary,
} from "./lib/get-agent-tool-summary";

/** How one tool's calls look in tool activity. */
export type AgentToolRenderer = {
  /** What the tool does, such as “Checking availability”. Names a single running call in the summary. */
  label: string;
  /** Shown before each row. Defaults to a wrench. */
  icon?: ReactNode;
  /** The row's content for a call, such as a summary of its output. Return nothing to keep the label. */
  render?: (call: AgentToolCall) => ReactNode;
};

/** Tool renderers by tool name. */
export type AgentToolRenderers = Readonly<
  Record<string, AgentToolRenderer | undefined>
>;

export type AgentToolActivityProps = Omit<
  ComponentProps<typeof Collapsible>,
  "children"
> & {
  calls: readonly AgentToolCall[];
  labels: AgentToolActivityLabels;
  renderers?: AgentToolRenderers;
  /** Replaces the neutral busy glyph while calls run. */
  indicator?: ReactNode;
};

function AgentToolCallContent({
  call,
  renderer,
  labels,
}: {
  call: AgentToolCall;
  renderer: AgentToolRenderer | undefined;
  labels: AgentToolActivityLabels;
}): ReactNode {
  const custom = renderer?.render?.(call);
  if (custom !== undefined && custom !== null) return custom;
  const label = renderer?.label ?? call.name;
  switch (call.state) {
    case "running":
      return <span className="motion-safe:animate-pulse">{label}</span>;
    case "failed":
      return (
        <>
          <span className="font-medium">{labels.callFailed(label)}</span>
          {call.error && (
            <span className="text-muted-foreground"> {call.error}</span>
          )}
        </>
      );
    case "denied":
      return (
        <span className="text-muted-foreground">
          {labels.callDenied(label)}
        </span>
      );
    default:
      return label;
  }
}

/** A run of tool calls behind one summary line, closed until the reader opens it. */
export function AgentToolActivity({
  calls,
  labels,
  renderers = {},
  indicator,
  className,
  ...props
}: AgentToolActivityProps): ReactElement {
  const summary = getAgentToolSummary(calls, labels, renderers);

  return (
    <Collapsible
      className={cn("flex min-w-0 flex-col", className)}
      data-slot="agent-tool-activity"
      data-status={summary.status}
      {...props}
    >
      <AgentDisclosureTrigger data-slot="agent-tool-activity-trigger">
        <AgentStatusIndicator indicator={indicator} status={summary.status}>
          {summary.label}
        </AgentStatusIndicator>
      </AgentDisclosureTrigger>
      <CollapsiblePanel className="motion-reduce:transition-none">
        <ul className="flex flex-col gap-1.5 ps-5 pt-1.5">
          {calls.map((call) => {
            const renderer = renderers[call.name];
            return (
              <li
                className="flex gap-1.5 text-foreground text-xs"
                data-slot="agent-tool-activity-row"
                data-state={call.state}
                key={call.id}
              >
                <span
                  aria-hidden="true"
                  className="flex h-lh w-3.5 shrink-0 items-center justify-center text-muted-foreground [&_svg:not([class*='size-'])]:size-3.5"
                >
                  {renderer?.icon ?? <WrenchIcon />}
                </span>
                <div className="min-w-0">
                  <AgentToolCallContent
                    call={call}
                    labels={labels}
                    renderer={renderer}
                  />
                </div>
              </li>
            );
          })}
        </ul>
      </CollapsiblePanel>
    </Collapsible>
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { Fragment, type ReactElement, type ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  AgentToolActivity,
  type AgentToolRenderers,
} from "./agent-tool-activity";
import type {
  AgentToolActivityLabels,
  AgentToolCall,
} from "./lib/get-agent-tool-summary";
import {
  type AgentTurnItem,
  groupAgentToolRuns,
} from "./lib/group-agent-tool-runs";

export type AgentTurnTools<TPart> = {
  /** Returns the tool call a part stands for, or `undefined` for any other part. */
  getCall: (part: TPart, index: number) => AgentToolCall | undefined;
  labels: AgentToolActivityLabels;
  /** How each tool's calls look, by tool name. */
  renderers?: AgentToolRenderers;
};

export type AgentTurnProps<TPart> = Omit<
  useRender.ComponentProps<"div">,
  "children"
> & {
  /** The turn's parts, in order, as your application models them. */
  parts: readonly TPart[];
  /** Renders a part that isn't a tool call. Return `null` to hide it; a hidden part doesn't split a run of tool calls. */
  renderPart: (part: TPart, index: number) => ReactNode;
  /** Groups each run of consecutive tool calls behind one tool activity disclosure. */
  tools?: AgentTurnTools<TPart>;
  /** Replaces the neutral busy glyph in tool activity. */
  indicator?: ReactNode;
};

function isHidden(node: ReactNode): boolean {
  return node === null || node === undefined || typeof node === "boolean";
}

/** The content of one agent turn: your parts in order, with runs of tool calls grouped. */
export function AgentTurn<TPart>({
  parts,
  renderPart,
  tools,
  indicator,
  className,
  render,
  ...props
}: AgentTurnProps<TPart>): ReactElement {
  const items = parts.map((part, index): AgentTurnItem<ReactNode> => {
    const call = tools?.getCall(part, index);
    if (call) return { call, type: "tool" };
    const node = renderPart(part, index);
    return isHidden(node) ? null : { content: node, type: "content" };
  });

  const defaultProps = {
    children: groupAgentToolRuns(items).map((segment) => {
      if (segment.type === "content")
        return <Fragment key={segment.key}>{segment.content}</Fragment>;
      // Tool segments only come from `tools.getCall`.
      return (
        tools && (
          <AgentToolActivity
            calls={segment.calls}
            indicator={indicator}
            key={segment.key}
            labels={tools.labels}
            renderers={tools.renderers}
          />
        )
      );
    }),
    className: cn("flex min-w-0 flex-col gap-3", className),
    "data-slot": "agent-turn",
  };

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type AgentAnnouncementState,
  type AgentPhase,
  getAgentAnnouncement,
  getAgentAnnouncerMessage,
} from "../lib/get-agent-announcement";

export type AgentAnnouncerLabels = Partial<
  Record<Exclude<AgentPhase, "idle">, string>
>;

export type AgentAnnouncerOptions = {
  phase: AgentPhase;
  /** Localized text for each phase. A phase without a label is never announced. */
  labels: AgentAnnouncerLabels;
  /** Replaces the phase label, such as the error or the approval question. */
  detail?: string;
  /** Changing it starts a new baseline, so a switched conversation isn't replayed. */
  conversationId?: string;
};

export function useAgentAnnouncer({
  phase,
  labels,
  detail,
  conversationId,
}: AgentAnnouncerOptions) {
  const [message, setMessage] = useState("");
  const previousRef = useRef<AgentAnnouncementState | null>(null);
  const text = phase === "idle" ? "" : (detail ?? labels[phase] ?? "");

  useEffect(() => {
    const next = { conversationId, phase, text };
    const announcement = getAgentAnnouncement(previousRef.current, next);
    previousRef.current = next;
    if (announcement)
      setMessage((current) => getAgentAnnouncerMessage(current, announcement));
  }, [conversationId, phase, text]);

  /** Announce a one-off result, such as a copied message. */
  const announce = useCallback((value: string): void => {
    if (value)
      setMessage((current) => getAgentAnnouncerMessage(current, value));
  }, []);

  return { announce, message };
}

export type AgentAnnouncerController = ReturnType<typeof useAgentAnnouncer>;

"use client";

import { useMediaQuery } from "@/registry/default/hooks/use-media-query";

/**
 * The agent family's reduced-motion check for motion timed in JavaScript, such as an
 * exit delay or an animation loop. CSS transitions use `motion-reduce:` variants instead.
 */
export function useAgentReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

export type AgentPhase =
  | "idle"
  | "thinking"
  | "working"
  | "approval"
  | "done"
  | "stopped"
  | "failed";

export type AgentAnnouncementState = {
  phase: AgentPhase;
  /** What this phase would say: a phase label, or a detail such as the error. */
  text: string;
  conversationId?: string;
};

function isBusy(phase: AgentPhase): boolean {
  return phase === "thinking" || phase === "working";
}

export function getAgentAnnouncement(
  previous: AgentAnnouncementState | null,
  next: AgentAnnouncementState,
): string {
  // A new mount or conversation only records a baseline; its state isn't replayed.
  if (previous === null || previous.conversationId !== next.conversationId)
    return "";
  if (next.phase !== previous.phase) {
    if (isBusy(next.phase) && isBusy(previous.phase)) return "";
    return next.text;
  }
  // Busy text is progress, streamed or not: only settled phases re-announce new text.
  if (isBusy(next.phase) || next.text === previous.text) return "";
  return next.text;
}

const REPEAT_MARK = " ";

/** Live regions skip unchanged content, so a repeat toggles a trailing no-break space. */
export function getAgentAnnouncerMessage(
  current: string,
  text: string,
): string {
  if (current === text) return `${text}${REPEAT_MARK}`;
  return text;
}

/** How long finished reasoning stays open before it closes, in milliseconds. */
export const AGENT_REASONING_CLOSE_DELAY = 1000;

export type AgentReasoningState = {
  streaming: boolean;
  open: boolean;
  /** A close is scheduled; the caller fires `close` after `AGENT_REASONING_CLOSE_DELAY`. */
  closing: boolean;
  /** The user opened or closed it during the current stream. */
  toggled: boolean;
};

export type AgentReasoningEvent =
  | { type: "stream"; streaming: boolean; autoOpen: boolean }
  | { type: "toggle"; open: boolean }
  | { type: "close" };

export function getInitialAgentReasoningState(
  streaming: boolean,
  defaultOpen: boolean = streaming,
): AgentReasoningState {
  return { closing: false, open: defaultOpen, streaming, toggled: false };
}

/**
 * Reasoning opens while it streams and closes a moment after it finishes.
 * Once the user toggles it, it stays as they left it until the next stream.
 */
export function getAgentReasoningState(
  state: AgentReasoningState,
  event: AgentReasoningEvent,
): AgentReasoningState {
  switch (event.type) {
    case "stream": {
      if (event.streaming === state.streaming) return state;
      if (event.streaming)
        return {
          closing: false,
          open: event.autoOpen || state.open,
          streaming: true,
          toggled: false,
        };
      return {
        ...state,
        closing: state.open && !state.toggled,
        streaming: false,
      };
    }
    case "toggle":
      return { ...state, closing: false, open: event.open, toggled: true };
    case "close":
      if (!state.closing) return state;
      return { ...state, closing: false, open: false };
  }
}

export const AGENT_SCROLL_OFFSET_VAR = "--agent-conversation-scroll-top";

/**
 * Base UI popover viewports crossfade a cloned snapshot of the outgoing content,
 * and a clone keeps attributes but not scroll position. Written to the viewport's
 * inline style, this offset travels with the clone so the transcript can be
 * translated back to where the reader was.
 */
export function getAgentScrollOffset(scrollTop: number): string {
  return `${Math.max(0, scrollTop)}px`;
}

import type { AgentPhase } from "./get-agent-announcement";

export type AgentToolCallState = "running" | "done" | "failed" | "denied";

/** One tool call, already mapped from your agent runtime. */
export type AgentToolCall = {
  id: string;
  /** Looks up the call's renderer in the tool-renderer registry. */
  name: string;
  state: AgentToolCallState;
  output?: unknown;
  /** Why the call failed, shown after its label. */
  error?: string;
};

/** Localized text for tool activity. */
export type AgentToolActivityLabels = {
  /** Summaries for a run of tool calls, by how many calls are in that state. */
  done: (count: number) => string;
  running: (count: number) => string;
  failed: (count: number) => string;
  denied: (count: number) => string;
  /** A failed call's row, given its tool label, such as “Checking availability failed.” */
  callFailed: (label: string) => string;
  /** A declined call's row, given its tool label, such as “Checking availability, declined”. */
  callDenied: (label: string) => string;
};

export type AgentToolSummaryStatus = Extract<
  AgentPhase,
  "working" | "done" | "failed"
>;

function inState(
  calls: readonly AgentToolCall[],
  state: AgentToolCallState,
): AgentToolCall[] {
  return calls.filter((call) => call.state === state);
}

/**
 * The status and one-line label for a run of tool calls. Failures win, then calls
 * still running, then declined calls. A single running call shows its own label.
 */
export function getAgentToolSummary(
  calls: readonly AgentToolCall[],
  labels: AgentToolActivityLabels,
  renderers: Readonly<Record<string, { label: string } | undefined>> = {},
): { status: AgentToolSummaryStatus; label: string } {
  const failed = inState(calls, "failed").length;
  if (failed > 0) return { label: labels.failed(failed), status: "failed" };

  const running = inState(calls, "running");
  if (running.length > 0) {
    const only = running.length === 1 ? running[0] : undefined;
    const label = only && renderers[only.name]?.label;
    return {
      label: label || labels.running(running.length),
      status: "working",
    };
  }

  const denied = inState(calls, "denied").length;
  if (denied > 0) return { label: labels.denied(denied), status: "done" };
  return { label: labels.done(calls.length), status: "done" };
}

import type { AgentToolCall } from "./get-agent-tool-summary";

/** One part of a turn: a tool call, some content, or nothing to show. */
export type AgentTurnItem<T> =
  | { type: "tool"; call: AgentToolCall }
  | { type: "content"; content: T }
  | null
  | undefined;

export type AgentTurnSegment<T> =
  | { type: "tools"; key: string; calls: AgentToolCall[] }
  | { type: "content"; key: string; content: T };

/**
 * Groups each run of consecutive tool calls into one segment. Hidden items are
 * dropped without splitting a run. Keys come from each segment's first position,
 * so a run that grows while streaming keeps its key.
 */
export function groupAgentToolRuns<T>(
  items: readonly AgentTurnItem<T>[],
): AgentTurnSegment<T>[] {
  const segments: AgentTurnSegment<T>[] = [];
  items.forEach((item, index) => {
    if (!item) return;
    if (item.type === "content") {
      segments.push({
        content: item.content,
        key: `content-${index}`,
        type: "content",
      });
      return;
    }
    const last = segments.at(-1);
    if (last?.type === "tools") last.calls.push(item.call);
    else
      segments.push({
        calls: [item.call],
        key: `tools-${index}`,
        type: "tools",
      });
  });
  return segments;
}

export const AGENT_RESULT_LIST_PREVIEW_COUNT = 5;

/** Splits a result list into the rows shown up front and the rows behind “show more”. A leftover of one isn’t worth a toggle. */
export function splitAgentResultItems<T>(
  items: readonly T[],
  previewCount: number = AGENT_RESULT_LIST_PREVIEW_COUNT,
): { visible: T[]; hidden: T[] } {
  if (items.length <= previewCount + 1)
    return { hidden: [], visible: [...items] };
  return {
    hidden: items.slice(previewCount),
    visible: items.slice(0, previewCount),
  };
}
